import { useState, type FormEvent } from 'react';
import { Plus, Edit2, Trash2, Star, RefreshCw, Loader2, Upload, X, Eye } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import I18nInput from '@/components/I18nInput';
import { useTestimonials, type ITestimonial } from '@/hooks/useTestimonials';
import { imgPath } from '@/utils/img-path';
import { createI18nText, type I18nText } from '@/lib/i18n-text';
import { batchTranslateI18n } from '@/lib/translate';
import { toast } from 'sonner';
import { useI18n } from '@/i18n/I18nContext';
import PageBreadcrumb from '@/components/PageBreadcrumb';
import { compressImage } from '@/lib/image-compress';
import { Image } from '@/components/ui/image';
import { Switch } from '@/components/ui/switch';
import { useSyncService } from '@/context/SyncServiceContext';
import SyncStatusBadge from '@/components/SyncStatusBadge';

const AVATAR_OPTIONS = [
  imgPath('/images/avatars/avatar-1.jpg'),
  imgPath('/images/avatars/avatar-2.jpg'),
  imgPath('/images/avatars/avatar-3.jpg'),
  imgPath('/images/avatars/avatar-4.jpg'),
];

interface TestiForm {
  customerName: I18nText;
  company: string;
  content: I18nText;
  rating: number;
  avatar: string;
  isVisible: boolean;
}

const emptyForm = (): TestiForm => ({
  customerName: createI18nText(''),
  company: '',
  content: createI18nText(''),
  rating: 5,
  avatar: AVATAR_OPTIONS[0],
  isVisible: true,
});

export default function AdminTestimonialsPage() {
  const { testimonials, addTestimonial, updateTestimonial, deleteTestimonial, showOnHomepage, setShowOnHomepage, loading } = useTestimonials();
  const { adminT } = useI18n();
  const { markDirty, syncModule, syncJsonFile, syncImagesInData, getStatus } = useSyncService();
  const syncStatus = getStatus('testimonials');
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [form, setForm] = useState<TestiForm>(emptyForm());
  const [dialogTranslating, setDialogTranslating] = useState(false);
  const [dialogProgress, setDialogProgress] = useState({ current: 0, total: 0 });
  const [pageTranslating, setPageTranslating] = useState(false);
  const [pageProgress, setPageProgress] = useState({ current: 0, total: 0 });

  const handleAvatarUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (!file.type.startsWith('image/')) {
      toast.error('Please upload a valid image file');
      return;
    }
    if (file.size > 2 * 1024 * 1024) {
      toast.error('Image size must be under 2MB');
      return;
    }
    try {
      const compressed = await compressImage(file, { maxWidth: 200, maxHeight: 200, quality: 0.78 });
      setForm({ ...form, avatar: compressed });
      toast.success('Avatar uploaded');
    } catch (err) {
      toast.error('Failed to process image: ' + (err instanceof Error ? err.message : String(err)));
    }
    // Reset input so the same file can be re-selected
    e.target.value = '';
  };

  const handleAvatarReset = () => {
    setForm({ ...form, avatar: AVATAR_OPTIONS[0] });
    toast.success('Avatar restored to default');
  };

  const isCustomAvatar = !AVATAR_OPTIONS.includes(form.avatar);

  const resetForm = () => {
    setForm(emptyForm());
    setEditingId(null);
  };

  const openCreate = () => {
    resetForm();
    setDialogOpen(true);
  };

  const openEdit = (t: ITestimonial) => {
    setForm({
      customerName: t.customerName,
      company: t.company,
      content: t.content,
      rating: t.rating,
      avatar: t.avatar,
      isVisible: t.isVisible !== false,
    });
    setEditingId(t.id);
    setDialogOpen(true);
  };

  const handleTranslateAll = async () => {
    const tasks = [
      { label: adminT('admin.customerName'), value: form.customerName },
      { label: 'Review Content', value: form.content },
    ].filter((t) => t.value.en.trim());

    if (!tasks.length) {
      toast.error('Please enter English text first');
      return;
    }
    setDialogTranslating(true);
    setDialogProgress({ current: 0, total: tasks.length });
    try {
      const results = await batchTranslateI18n(tasks, (cur, total) => {
        setDialogProgress({ current: cur, total });
      });
      const newForm = { ...form };
      const formDict = newForm as unknown as Record<string, I18nText>;
      for (let i = 0; i < results.length; i++) {
        const task = tasks[i];
        if (task && formDict[task.label] && !results[i].skipped && results[i].success) {
          formDict[task.label] = results[i].value;
        }
      }
      setForm(newForm);
      const successCount = results.filter((r) => r.success).length;
      const failed = results.filter((r) => !r.success && !r.skipped);
      if (failed.length > 0) {
        toast.warning(`Translated ${successCount}/${results.length}. Failed: ${failed.map((f) => f.label).join(', ')}`);
      } else {
        toast.success('Translated to all languages');
      }
    } catch {
      toast.error('Translation failed. Please try again.');
    } finally {
      setDialogTranslating(false);
      setDialogProgress({ current: 0, total: 0 });
    }
  };

  const handlePageTranslateAll = async () => {
    if (testimonials.length === 0) {
      toast.warning('No testimonials to translate');
      return;
    }
    const fieldNames: Array<'customerName' | 'content'> = ['customerName', 'content'];
    const tasks = testimonials.flatMap((t) =>
      fieldNames.map((f) => ({
        label: `${t.customerName.en.slice(0, 20) || 'Anonymous'} / ${f}`,
        value: t[f],
      })),
    ).filter((t) => t.value.en.trim());

    if (tasks.length === 0) {
      toast.warning('No English content found to translate');
      return;
    }

    setPageTranslating(true);
    setPageProgress({ current: 0, total: tasks.length });
    try {
      const results = await batchTranslateI18n(tasks, (cur, total) => {
        setPageProgress({ current: cur, total });
      });

      let resultIdx = 0;
      for (const t of testimonials) {
        const updates: Partial<ITestimonial> = {};
        let changed = false;
        for (const f of fieldNames) {
          if (t[f].en.trim()) {
            const r = results[resultIdx];
            if (r && !r.skipped && r.success) {
              updates[f] = r.value;
              changed = true;
            }
            resultIdx++;
          }
        }
        if (changed) {
          updateTestimonial(t.id, { ...t, ...updates });
          markDirty('testimonials');
        }
      }

      const successCount = results.filter((r) => r.success).length;
      const failed = results.filter((r) => !r.success && !r.skipped);
      if (failed.length > 0) {
        toast.warning(`Translated ${successCount}/${results.length}. ${failed.length} failed.`);
      } else {
        toast.success(`Translation completed: ${successCount} fields translated`);
      }
    } catch {
      toast.error('Translation failed. Please try again.');
    } finally {
      setPageTranslating(false);
      setPageProgress({ current: 0, total: 0 });
    }
  };

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    if (!form.customerName.en.trim() || !form.content.en.trim()) {
      toast.error('Customer name and English content are required');
      return;
    }

    if (editingId) {
      updateTestimonial(editingId, {
        customerName: form.customerName,
        company: form.company,
        content: form.content,
        rating: form.rating,
        avatar: form.avatar,
        isVisible: form.isVisible,
      });
      markDirty('testimonials');
      toast.success(adminT('admin.testimonialUpdated'));
    } else {
      addTestimonial({
        customerName: form.customerName,
        company: form.company,
        content: form.content,
        rating: form.rating,
        avatar: form.avatar,
        createdAt: Date.now(),
        isVisible: form.isVisible,
      });
      markDirty('testimonials');
      toast.success(adminT('admin.testimonialCreated'));
    }
    setDialogOpen(false);
    resetForm();
  };

  const handleToggleVisible = (id: string, visible: boolean) => {
    updateTestimonial(id, { isVisible: visible });
    markDirty('testimonials');
  };

  const handleDelete = (id: string) => {
    if (window.confirm(adminT('admin.deleteTestimonial'))) {
      deleteTestimonial(id);
      markDirty('testimonials');
      toast.success(adminT('admin.testimonialDeleted'));
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-20">
        <div className="w-8 h-8 border-2 border-primary border-t-transparent rounded-full animate-spin" />
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Breadcrumb */}
      <PageBreadcrumb
        firstItem={{ label: adminT('admin.dashboard'), href: '/admin/dashboard', icon: 'dashboard' }}
        items={[
          { label: adminT('admin.testimonials') },
        ]}
      />

      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-foreground">Testimonials Management</h1>
          <p className="text-sm text-muted-foreground mt-1">
            {testimonials.length} customer reviews displayed on homepage
          </p>
        </div>
        <div className="flex items-center gap-2 flex-wrap">
          <SyncStatusBadge status={syncStatus} />
          <Button
            variant="outline"
            size="sm"
            onClick={() =>
              syncModule('testimonials', 'Testimonials', async (config) => {
                const dataWithImages = await syncImagesInData(
                  config,
                  testimonials,
                  'testimonials',
                  ['avatar' as any]
                );
                await syncJsonFile(
                  config,
                  'data/testimonials.json',
                  { showOnHomepage, data: dataWithImages },
                  'Update testimonials data'
                );
              })
            }
            disabled={syncStatus === 'syncing'}
            className="text-xs h-9"
          >
            <Upload className="size-3.5 mr-1.5" />
            Sync to GitHub
          </Button>
          <Button
            variant="outline"
            size="sm"
            onClick={handlePageTranslateAll}
            disabled={pageTranslating || testimonials.length === 0}
            className="text-xs h-9"
          >
            {pageTranslating ? (
              <>
                <Loader2 className="size-3.5 mr-1.5 animate-spin" />
                Translating {pageProgress.current}/{pageProgress.total}...
              </>
            ) : (
              <>
                <RefreshCw className="size-3.5 mr-1.5" />
                Translate All
              </>
            )}
          </Button>
          <Button onClick={openCreate} className="bg-primary hover:bg-primary/90 text-primary-foreground">
            <Plus className="size-4 mr-2" />
            Add Testimonial
          </Button>
        </div>
      </div>

      <Card className="border-primary/20 bg-primary/5">
        <CardContent className="py-4 px-5 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
          <div>
            <h3 className="text-sm font-semibold text-foreground flex items-center gap-2">
              <Eye className="size-4 text-primary" />
              Show Testimonials on Homepage
            </h3>
            <p className="text-xs text-muted-foreground mt-1">
              Toggle the entire testimonials section display on the homepage. Individual testimonial visibility settings are preserved.
            </p>
          </div>
          <div className="flex items-center gap-3">
            <span className="text-xs text-muted-foreground">
              {showOnHomepage ? 'Showing on homepage' : 'Hidden on homepage'}
            </span>
            <Switch
              checked={showOnHomepage}
              onCheckedChange={(val) => {
                setShowOnHomepage(val);
                markDirty('testimonials');
                toast.success(val ? 'Testimonials section will show on homepage' : 'Testimonials section hidden on homepage');
              }}
            />
          </div>
        </CardContent>
      </Card>

      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base">Customer Testimonials</CardTitle>
        </CardHeader>
        <CardContent className="p-0">
          <div className="w-full overflow-x-auto">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead className="whitespace-nowrap w-16">Avatar</TableHead>
                  <TableHead className="whitespace-nowrap">{adminT('admin.customer')}</TableHead>
                  <TableHead className="whitespace-nowrap">{adminT('admin.company')}</TableHead>
                  <TableHead className="whitespace-nowrap">{adminT('admin.rating')}</TableHead>
                  <TableHead className="whitespace-nowrap">Content (EN)</TableHead>
                  <TableHead className="whitespace-nowrap">Show on site</TableHead>
                  <TableHead className="whitespace-nowrap text-right">{adminT('admin.actions')}</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {testimonials.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={7} className="text-center text-muted-foreground py-8">
                      No testimonials yet
                    </TableCell>
                  </TableRow>
                ) : (
                  testimonials.map((t) => (
                    <TableRow key={t.id}>
                       <TableCell>
                         <div className="relative w-9 h-9 rounded-full overflow-hidden bg-muted">
                           <Image src={t.avatar} alt={t.customerName.en} className="absolute inset-0 w-full h-full object-cover" />
                         </div>
                       </TableCell>
                      <TableCell className="font-medium">{t.customerName.en}</TableCell>
                      <TableCell className="text-sm text-muted-foreground">{t.company}</TableCell>
                      <TableCell>
                        <div className="flex items-center gap-0.5">
                          {Array.from({ length: 5 }).map((_, i) => (
                            <Star
                              key={i}
                              className={`size-3.5 ${
                                i < t.rating
                                  ? 'fill-amber-400 text-amber-400'
                                  : 'text-muted-foreground/30'
                              }`}
                            />
                          ))}
                        </div>
                      </TableCell>
                       <TableCell>
                         <span className="text-sm text-muted-foreground line-clamp-2 block max-w-md">
                           {t.content.en}
                         </span>
                       </TableCell>
                       <TableCell>
                         <Switch
                           checked={t.isVisible !== false}
                           onCheckedChange={(checked) => handleToggleVisible(t.id, checked)}
                         />
                       </TableCell>
                       <TableCell className="text-right">
                        <div className="flex items-center justify-end gap-1">
                          <Button
                            variant="ghost"
                            size="icon"
                            onClick={() => openEdit(t)}
                            className="h-8 w-8"
                          >
                            <Edit2 className="size-3.5" />
                          </Button>
                          <Button
                            variant="ghost"
                            size="icon"
                            onClick={() => handleDelete(t.id)}
                            className="h-8 w-8 text-destructive hover:text-destructive hover:bg-destructive/10"
                          >
                            <Trash2 className="size-3.5" />
                          </Button>
                        </div>
                      </TableCell>
                    </TableRow>
                  ))
                )}
              </TableBody>
            </Table>
          </div>
        </CardContent>
      </Card>

      {/* Dialog */}
      <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
        <DialogContent className="max-w-xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle className="flex items-center justify-between flex-wrap gap-2">
              <span>{editingId ? adminT('admin.editTestimonial') : adminT('admin.addTestimonial')}</span>
              <Button
                type="button"
                size="sm"
                variant="outline"
                onClick={handleTranslateAll}
                disabled={dialogTranslating}
                className="text-xs h-8"
              >
                {dialogTranslating ? (
                  <>
                    <Loader2 className="size-3.5 mr-1.5 animate-spin" />
                    Translating...
                  </>
                ) : (
                  <>
                    <RefreshCw className="size-3 mr-1.5" /> Translate Content
                  </>
                )}
              </Button>
            </DialogTitle>
          </DialogHeader>
          <form onSubmit={handleSubmit} className="space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-xs font-medium text-foreground mb-1.5 block">
                  Customer Name *
                </label>
                <I18nInput
                  value={form.customerName}
                  onChange={(v) => setForm({ ...form, customerName: v })}
                  placeholder="John Doe"
                />
              </div>
              <div>
                <label className="text-xs font-medium text-foreground mb-1.5 block">
                  Company
                </label>
                <Input
                  value={form.company}
                  onChange={(e) => setForm({ ...form, company: e.target.value })}
                  placeholder="Acme Inc."
                />
              </div>
            </div>
            <div>
              <label className="text-xs font-medium text-foreground mb-1.5 block">{adminT('admin.rating')}</label>
              <div className="flex items-center gap-1">
                {Array.from({ length: 5 }).map((_, i) => (
                  <button
                    type="button"
                    key={i}
                    onClick={() => setForm({ ...form, rating: i + 1 })}
                    className="p-0.5 hover:scale-110 transition-transform"
                  >
                    <Star
                      className={`size-6 ${
                        i < form.rating
                          ? 'fill-amber-400 text-amber-400'
                          : 'text-muted-foreground/30'
                      }`}
                    />
                  </button>
                ))}
              </div>
            </div>
            <I18nInput
              label="Review Content"
              value={form.content}
              onChange={(v) => setForm({ ...form, content: v })}
              placeholder="Write your customer review..."
              multiline
              rows={5}
              
            />
            <div>
              <label className="text-xs font-medium text-foreground mb-1.5 block">Avatar</label>
              {/* Current avatar preview */}
              <div className="flex items-center gap-3 mb-3">
                <div className="relative w-14 h-14 rounded-full overflow-hidden bg-muted border border-border">
                  <Image src={form.avatar} alt="avatar preview" className="absolute inset-0 w-full h-full object-cover" />
                </div>
                <div className="flex flex-col gap-1.5">
                  <label
                    htmlFor="testimonial-avatar-upload"
                    className="inline-flex items-center gap-1.5 px-3 h-8 text-xs font-medium rounded-md bg-secondary text-secondary-foreground hover:bg-secondary/80 cursor-pointer transition-colors"
                  >
                    <Upload className="size-3.5" />
                    Upload Custom
                  </label>
                  <input
                    id="testimonial-avatar-upload"
                    type="file"
                    accept="image/*"
                    onChange={handleAvatarUpload}
                    className="sr-only"
                  />
                  {isCustomAvatar && (
                    <button
                      type="button"
                      onClick={handleAvatarReset}
                      className="inline-flex items-center gap-1 px-3 h-8 text-xs font-medium rounded-md border border-border text-muted-foreground hover:text-foreground hover:bg-accent/30 transition-colors"
                    >
                      <X className="size-3.5" />
                      Remove Custom
                    </button>
                  )}
                </div>
              </div>
              <p className="text-[11px] text-muted-foreground mb-2">
                JPG/PNG/WebP, max 2MB. Or choose from presets below:
              </p>
              <div className="flex gap-2 flex-wrap">
                {AVATAR_OPTIONS.slice(0, 8).map((img, i) => (
                  <button
                    key={i}
                    type="button"
                    onClick={() => setForm({ ...form, avatar: img })}
                    className={`relative w-10 h-10 rounded-full overflow-hidden border-2 transition-all ${
                      form.avatar === img ? 'border-primary scale-110' : 'border-transparent hover:border-border'
                    }`}
                    title={`Preset ${i + 1}`}
                  >
                    <Image src={img} alt={`avatar-${i}`} className="absolute inset-0 w-full h-full object-cover" />
                  </button>
                ))}
              </div>
            </div>
            <DialogFooter className="pt-2">
              <Button type="button" variant="outline" onClick={() => setDialogOpen(false)}>
                Cancel
              </Button>
              <Button type="submit" className="bg-primary hover:bg-primary/90">
                {editingId ? adminT('admin.edit') : adminT('admin.addTestimonial')}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
    </div>
  );
}
